        public Projectile Duplicate(
            IProjectileGetter item,
            FormKey formKey,
            TranslationCrystal? copyMask)
        {
            var newRec = new Projectile(formKey, item.FormVersion);
            newRec.DeepCopyIn(item, default(ErrorMaskBuilder?), copyMask);
            return newRec;
        }
        
