        public void DeepCopyIn(
            IProjectile item,
            IProjectileGetter rhs,
            ErrorMaskBuilder? errorMask,
            TranslationCrystal? copyMask,
            bool deepCopy)
        {
            try
            {
                DeepCopyInInternal(
                    item: item,
                    rhs: rhs,
                    errorMask: errorMask,
